  constructor(message) {
    super(message)
    this.line = 0
  }
}

const fail = (m) => {
  throw new ParseError(m)
}

const newTable = () => ({ t: 'table', map: new Map(), defined: false })
const isWs = (c) => c === ' ' || c === '\t'
const BARE = /[A-Za-z0-9_-]/

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (this.i < this.s.length && isWs(this.s[this.i])) this.i++
  }
  /** At end of line or at a comment start. */
  atEnd() {
    return this.i >= this.s.length || this.c === '#' || this.c === ';'
  }
}

function parseBasic(L) {
  // L.c is the opening quote
  L.i++
  let out = ''
  for (;;) {
    if (L.i >= L.s.length) fail('unterminated string')
    const ch = L.s[L.i]
    if (ch === '"') {
      L.i++
      return out
    }
    if (ch === '\\') {
      L.i++
      if (L.i >= L.s.length) fail('unterminated string')
      const e = L.s[L.i]
      const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(m, e)) {
        out += m[e]
        L.i++
      } else if (e === 'u') {
        const h = L.s.slice(L.i + 1, L.i + 5)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 5
      } else {
        const cp = String.fromCodePoint(L.s.codePointAt(L.i))
        fail('invalid escape \\' + cp)
      }
    } else {
      out += ch
      L.i++
    }
  }
}

function parseLiteral(L) {
  const j = L.s.indexOf("'", L.i + 1)
  if (j < 0) fail('unterminated string')
  const out = L.s.slice(L.i + 1, j)
  L.i = j + 1
  return out
}

function parseName(L) {
  L.ws()
  const ch = L.c
  if (ch === '"') return parseBasic(L)
  if (ch === "'") return parseLiteral(L)
  const st = L.i
  while (L.i < L.s.length && BARE.test(L.s[L.i])) L.i++
  if (L.i === st) fail('expected a name')
  return L.s.slice(st, L.i)
}

