    L.i++
    const items = []
    let first = true
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated array')
      if (L.c === ']') {
        L.i++
        break
      }
      items.push(parseValue(L, prefix))
      first = false
      L.ws()
      if (L.c === ',') {
        L.i++
        continue
      }
      if (L.c === ']') {
        L.i++
        break
      }
      fail('unterminated array')
    }
    void first
    return { t: 'array', items, tables: false }
  }
  if (ch === '{') {
    L.i++
    const tbl = newTable()
    L.ws()
    if (L.c === '}') {
      L.i++
      return tbl
    }
    for (;;) {
      L.ws()
      if (L.i >= L.s.length || L.c === '#' || L.c === ';') fail('unterminated inline table')
      const parts = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected = in an inline table')
      L.i++
      const base = prefix === null ? [] : [prefix]
      const val = parseValue(L, [...base, ...parts].join('.'))
      assign(tbl, parts, val, prefix)
      L.ws()
      if (L.c === ',') {
        L.i++
        continue
      }
      if (L.c === '}') {
        L.i++
        return tbl
      }
      fail('unterminated inline table')
    }
