  const t = walk(tbl, parts.slice(0, -1), prefix)
  const last = parts[parts.length - 1]
  if (t.map.has(last)) fail(`key ${join(prefix, parts)} is defined twice`)
  t.map.set(last, val)
}

function trailing(L, msg) {
  L.ws()
  if (!L.atEnd()) fail(msg)
}

