  const close = array ? ']]' : ']'
  if (L.s.startsWith(close, L.i)) L.i += close.length
  else fail('unterminated table header')
  trailing(L, 'trailing text after a table header')
  const path = (n) => parts.slice(0, n).join('.')
  const parent = walk(root, parts.slice(0, -1), '')
  const last = parts[parts.length - 1]
  const ex = parent.map.get(last)
  if (array) {
    if (!ex) {
      const t = newTable()
      parent.map.set(last, { t: 'array', items: [t], tables: true })
      return t
    }
    if (ex.t !== 'array' || !ex.tables) fail(path(parts.length) + ' is not an array of tables')
    const t = newTable()
    ex.items.push(t)
    return t
  }
  if (!ex) {
    const t = newTable()
    t.defined = true
    parent.map.set(last, t)
    return t
  }
  if (ex.t !== 'table') fail(path(parts.length) + ' is not a table')
  if (ex.defined) fail(`table ${path(parts.length)} is defined twice`)
  ex.defined = true
  return ex
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.i >= L.s.length || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        const array = L.s[L.i + 1] === '['
        const save = L.i
        cur = parseHeader(L, root)
        L.i = save
        void array
        continue
      }
      const parts = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const val = parseValue(L, join(curPath, parts))
      trailing(L, 'trailing text after a value')
      assign(cur, parts, val, curPath)
    } catch (e) {
      if (e instanceof ParseError) e.line = n + 1
      throw e
    }
  }
  return root
}
"}

